alter table public.profiles add column if not exists coach_id uuid references public.coaches(id) on delete set null;
create table if not exists public.courts(id uuid primary key default gen_random_uuid(),name text not null unique,is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.court_slots(id uuid primary key default gen_random_uuid(),court_id uuid not null references public.courts(id) on delete cascade,start_at timestamptz not null,end_at timestamptz not null,slot_type text not null check(slot_type in('open_pt','class','blocked')),title text,status text not null default 'open' check(status in('open','held','booked')),created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),check(end_at>start_at));
create table if not exists public.pt_session_requests(id uuid primary key default gen_random_uuid(),slot_id uuid not null references public.court_slots(id) on delete cascade,coach_id uuid not null references public.coaches(id) on delete cascade,requested_by uuid not null references auth.users(id) on delete cascade,client_name text,status text not null default 'requested' check(status in('requested','approved','declined','cancelled','completed')),fee_amount numeric not null default 5 check(fee_amount>=0),fee_status text not null default 'unpaid' check(fee_status in('unpaid','paid','waived')),payment_method text check(payment_method in('cash','venmo','other')),notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(slot_id));
alter table public.courts enable row level security;alter table public.court_slots enable row level security;alter table public.pt_session_requests enable row level security;
create or replace function public.can_manage_court_schedule() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.profiles where id=auth.uid() and role in('owner_admin','program_director'));$$;
create policy "authenticated view courts" on public.courts for select to authenticated using(true);create policy "schedule managers manage courts" on public.courts for all to authenticated using(public.can_manage_court_schedule()) with check(public.can_manage_court_schedule());
create policy "authenticated view court slots" on public.court_slots for select to authenticated using(true);create policy "schedule managers manage court slots" on public.court_slots for all to authenticated using(public.can_manage_court_schedule()) with check(public.can_manage_court_schedule());
create policy "managers or assigned coaches view pt requests" on public.pt_session_requests for select to authenticated using(public.can_manage_court_schedule() or requested_by=auth.uid() or coach_id=(select coach_id from public.profiles where id=auth.uid()));
create policy "linked coaches request pt sessions" on public.pt_session_requests for insert to authenticated with check(requested_by=auth.uid() and coach_id=(select coach_id from public.profiles where id=auth.uid()));
create policy "schedule managers manage pt requests" on public.pt_session_requests for update to authenticated using(public.can_manage_court_schedule()) with check(public.can_manage_court_schedule());
create policy "schedule managers view coach profile links" on public.profiles for select to authenticated using(public.can_manage_court_schedule());
create policy "schedule managers update coach profile links" on public.profiles for update to authenticated using(public.can_manage_court_schedule()) with check(public.can_manage_court_schedule());
